// @ts-nocheck
const Users={currentPage:1,pageSize:20,searchParams:{},async render(){document.getElementById("pageContent").innerHTML='\n            <div class="card">\n                <div class="card-header">\n                    <h3 class="card-title">Quản lý người dùng</h3>\n                </div>\n                <div class="card-body">\n                    <div class="search-box mb-3">\n                        <select class="form-control" id="searchType" style="width: 150px;">\n                            <option value="email">Email</option>\n                            <option value="id">ID</option>\n                        </select>\n                        <input type="text" class="form-control search-input" id="searchInput" \n                               placeholder="Nhập từ khóa tìm kiếm...">\n                        <button class="btn btn-primary" onclick="Users.search()">\n                            <i class="fas fa-search"></i> Tìm kiếm\n                        </button>\n                        <button class="btn btn-outline" onclick="Users.reset()">\n                            <i class="fas fa-redo"></i> Reset\n                        </button>\n                    </div>\n                    \n                    <div id="usersTable">\n                        <div class="loading-container">\n                            <div class="loading-spinner"></div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        ',await Users.loadUsers()},async loadUsers(t=1){Users.currentPage=t;try{const t={page:Users.currentPage,limit:Users.pageSize,...Users.searchParams},n=await API.users.search(t);Users.renderTable(n)}catch(t){console.error("Failed to load users:",t),document.getElementById("usersTable").innerHTML='\n                <div class="alert alert-danger">\n                    Không thể tải danh sách người dùng\n                </div>\n            '}},renderTable(t){const{data:n,total:e,current:s,pageSize:a}=t,r=Math.ceil(e/a);if(!n||0===n.length)return void(document.getElementById("usersTable").innerHTML='\n                <div class="alert alert-info">\n                    Không tìm thấy người dùng nào\n                </div>\n            ');let d='\n            <div class="table-responsive">\n                <table class="data-table">\n                    <thead>\n                        <tr>\n                            <th>ID</th>\n                            <th>Email</th>\n                            <th>Gói dịch vụ</th>\n                            <th>Đã dùng</th>\n                            <th>Giới hạn</th>\n                            <th>Thiết bị</th>\n                            <th>Hạn dùng</th>\n                            <th>Hành động</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n        ';n.forEach((t=>{const n=App.formatBytes((t.u||0)+(t.d||0)),e=App.formatBytes(t.transfer_enable||0),s=t.plan_name||'<span class="text-muted">Không có</span>',a=t.expired_at?App.formatDate(t.expired_at):"-",r=t.expired_at&&t.expired_at>Date.now()/1e3?"text-success":"text-danger";d+=`\n                <tr>\n                    <td>${t.id}</td>\n                    <td>${t.email}</td>\n                    <td>${s}</td>\n                    <td>${n}</td>\n                    <td>${e}</td>\n                    <td>${t.alive_ip||0}</td>\n                    <td><span class="${r}">${a}</span></td>\n                    <td>\n                        <button class="btn btn-sm btn-primary" onclick="Users.viewDetails(${t.id})" title="Chi tiết">\n                            <i class="fas fa-eye"></i>\n                        </button>\n                        <button class="btn btn-sm btn-info" onclick="Users.copySubscribe('${t.subscribe_url}')" title="Copy link">\n                            <i class="fas fa-copy"></i>\n                        </button>\n                        <button class="btn btn-sm btn-warning" onclick="App.showQRCode('${t.subscribe_url}')" title="QR Code">\n                            <i class="fas fa-qrcode"></i>\n                        </button>\n                    </td>\n                </tr>\n            `})),d+="\n                    </tbody>\n                </table>\n            </div>\n        ",r>1&&(d+=App.createPagination(s,r,"Users.loadUsers")),d+=`\n            <div class="mt-3 text-muted">\n                Hiển thị ${(s-1)*a+1} - ${Math.min(s*a,e)} trong tổng số ${e} người dùng\n            </div>\n        `,document.getElementById("usersTable").innerHTML=d},search(){const t=document.getElementById("searchType").value,n=document.getElementById("searchInput").value.trim();Users.searchParams=n?{[t]:n}:{},Users.loadUsers(1)},reset(){document.getElementById("searchInput").value="",Users.searchParams={},Users.loadUsers(1)},copySubscribe(t){App.copyToClipboard(t)},async viewDetails(t){try{const n=(await API.users.getById(t)).data,e=`\n                <div class="user-details">\n                    <table class="detail-table">\n                        <tr>\n                            <td><strong>ID:</strong></td>\n                            <td>${n.id}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Email:</strong></td>\n                            <td>${n.email}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Số dư:</strong></td>\n                            <td>${App.formatCurrency(n.balance)}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Hoa hồng:</strong></td>\n                            <td>${App.formatCurrency(n.commission_balance)}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Gói dịch vụ:</strong></td>\n                            <td>${n.plan_id?`ID: ${n.plan_id}`:"Không có"}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Tốc độ:</strong></td>\n                            <td>${n.speed_limit||0} Mbps</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Thiết bị tối đa:</strong></td>\n                            <td>${n.device_limit||0}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Đã dùng:</strong></td>\n                            <td>${App.formatBytes((n.u||0)+(n.d||0))}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Giới hạn:</strong></td>\n                            <td>${App.formatBytes(n.transfer_enable||0)}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Ngày hết hạn:</strong></td>\n                            <td>${n.expired_at?App.formatDate(n.expired_at):"Không giới hạn"}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>UUID:</strong></td>\n                            <td style="word-break: break-all;">${n.uuid}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Token:</strong></td>\n                            <td style="word-break: break-all;">${n.token}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Trạng thái:</strong></td>\n                            <td>${n.banned?'<span class="text-danger">Đã khóa</span>':'<span class="text-success">Hoạt động</span>'}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Ngày đăng ký:</strong></td>\n                            <td>${App.formatDate(n.created_at)}</td>\n                        </tr>\n                    </table>\n                </div>\n                <style>\n                    .user-details { padding: 20px; }\n                    .detail-table { width: 100%; }\n                    .detail-table td { padding: 8px; border-bottom: 1px solid #eee; }\n                    .detail-table tr:last-child td { border-bottom: none; }\n                </style>\n            `;App.showModal(`Chi tiết người dùng #${t}`,e)}catch(t){App.showToast("error","Lỗi","Không thể tải thông tin người dùng")}}};